"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8365],{20900:e=>{e.exports=JSON.parse('{"functions":[{"name":"positionKey","desc":"A key identifying where the observers stand, at cell resolution.\\n\\nUsed to decide when a chunk\'s wall ordering has gone stale. Cell resolution\\nrather than detail-block resolution because a block is eight cells across,\\nand waiting that long to re-prioritise shows up as walls filling in behind\\nthe player.\\n\\nSorted, so the key does not change just because the query returned two\\nplayers in a different order.","params":[{"name":"positions","desc":"","lua_type":"{ Position }"}],"returns":[{"desc":"Empty when there are no observers.","lua_type":"string"}],"function_type":"static","source":{"line":43,"path":"src/main/shared/helpers/wallOrder.luau"}},{"name":"sortRunsFarthestFirst","desc":"Orders wall runs farthest-observer-first, in place.\\n\\nFarthest first because the build loop pops the **last** element, so the\\nnearest wall is the next one built. Distance is Chebyshev, matching every\\nother radius in the streaming pipeline.\\n\\nReturns whether it ordered anything. With no observers there is no meaningful\\norder, and the caller must not record a sort key it did not earn \u2014 otherwise\\nthe ordering would be skipped forever once observers appear.","params":[{"name":"runs","desc":"Sorted in place.","lua_type":"{ Run }"},{"name":"baseX","desc":"Chunk origin column, in world cells.","lua_type":"number"},{"name":"baseY","desc":"Chunk origin row, in world cells.","lua_type":"number"},{"name":"positions","desc":"Observer positions in world-cell space.","lua_type":"{ Position }"}],"returns":[{"desc":"True if the runs are now ordered.","lua_type":"boolean"}],"function_type":"static","source":{"line":75,"path":"src/main/shared/helpers/wallOrder.luau"}}],"properties":[],"types":[{"name":"Position","desc":"Somewhere an observer is standing.","fields":[{"name":"x","lua_type":"number","desc":"Column in world-cell space."},{"name":"y","lua_type":"number","desc":"Row in world-cell space."}],"source":{"line":26,"path":"src/main/shared/helpers/wallOrder.luau"}}],"name":"wallOrder","desc":"Decides which wall the build loop should put up next: the one closest to a\\nplayer.\\n\\nPure arithmetic over plain tables, with no ECS dependency, which is what\\nmakes generation radiating outward from the player something that can be\\ntested directly rather than inferred from watching a playtest.","tags":["shared-helper"],"source":{"line":13,"path":"src/main/shared/helpers/wallOrder.luau"}}')}}]);